const listProposalChanges = `-- name: ListProposalChanges :many
SELECT id, workspace_id, proposal_id, field_path, op, before_digest, after_digest, before_value, after_value, created_at FROM proposal_changes
WHERE workspace_id = $1 AND proposal_id = $2
ORDER BY created_at, id
`

type ListProposalChangesParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	ProposalID  pgtype.UUID `json:"proposal_id"`
}

func (q *Queries) ListProposalChanges(ctx context.Context, arg ListProposalChangesParams) ([]ProposalChange, error) {
	rows, err := q.db.Query(ctx, listProposalChanges, arg.WorkspaceID, arg.ProposalID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProposalChange{}
	for rows.Next() {
		var i ProposalChange
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ProposalID,
			&i.FieldPath,
			&i.Op,
			&i.BeforeDigest,
			&i.AfterDigest,
			&i.BeforeValue,
			&i.AfterValue,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

